package org.telegram.messenger;import java.util.*;public final class NotificationCenter {public static final int activeAccountChanged=1,screenStateChanged=2;private static final NotificationCenter global=new NotificationCenter();public static NotificationCenter getGlobalInstance(){return global;}public interface NotificationCenterDelegate{void didReceivedNotification(int id,int account,Object...args);}public final List<NotificationCenterDelegate> observers=new ArrayList<>();public void addObserver(NotificationCenterDelegate d,int id){observers.add(d);}public void postNotificationName(int id,Object...args){for(NotificationCenterDelegate d:observers)d.didReceivedNotification(id,0,args);}}
